    private void btnOKActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnOKActionPerformed
        // TODO add your handling code here:
        String id = txtId.getText();
        String name = txtName.getText();
        String surname = txtSurname.getText();
        //ComboBox
        String age = (String) cbxAge.getSelectedItem();//get อายุมาจาก combobox
        //Radio
        String gender = "";
        if (rdoMale.isSelected()) {
            gender = "\nGender Male";
        } else {
            gender = "\nGender Female";
        }
        //ChekBox
        //chDev.isSelected()
        String career = "";
        
        if (chDev.isSelected()) {
            career += "Developer ";
        }
        if (chSA.isSelected()) {
            career += "System Analyst ";
        }
        if (chBackEnd.isSelected()) {
            career += "BackEnd ";
        }
        txaResult.setText("ID " + id
                + "\nName " + name
                + "\nSurname " + surname
                + "\nAge " + age
                + "" + gender
                + "\nCareer " + career);
    }//GEN-LAST:event_btnOKActionPerformed

